import styled from "styled-components";
import { Container } from "@/components/layout/Container";
import { Section } from "@/components/layout/Section";
import { Reveal, useToast } from "@/components/ui";
import { invitation } from "@/data/invitation";
import { useCopyToClipboard } from "@/hooks/useCopyToClipboard";
import { formatAccountForCopy, selectGiftAccountGroups } from "@/lib/gift";
import type { GiftAccountEntry, GiftAccountGroup } from "@/types/invitation";

/** 계좌 정보를 페이지에 바로 노출하고, 각 행을 누르면 복사한다. */
export function Gift() {
  const groups = selectGiftAccountGroups(invitation.couple);

  if (groups.length === 0) return null;

  return (
    <Container>
      <Section title="축하의 마음을 전하세요" ornament>
        <Reveal>
          <Description>
            축하의 마음을 전하실 곳을 안내드립니다.
            <br />
            계좌번호를 누르면 복사됩니다.
          </Description>

          <AccountGroups>
            {groups.map((group) => (
              <AccountGroup key={group.label} group={group} />
            ))}
          </AccountGroups>
        </Reveal>
      </Section>
    </Container>
  );
}

function AccountGroup({ group }: { group: GiftAccountGroup }) {
  return (
    <GroupCard aria-labelledby={`gift-${group.label}`}>
      <GroupTitle id={`gift-${group.label}`}>{group.label}</GroupTitle>
      <AccountList>
        {group.entries.map((entry) => (
          <AccountRow
            key={`${entry.relation}-${entry.account.number}`}
            entry={entry}
          />
        ))}
      </AccountList>
    </GroupCard>
  );
}

function AccountRow({ entry }: { entry: GiftAccountEntry }) {
  const { copy } = useCopyToClipboard();
  const { showToast } = useToast();

  const handleCopy = async () => {
    const copied = await copy(formatAccountForCopy(entry));

    /* 성공했을 때만 성공을 알린다. 계좌번호에서 이 구분은 중요하다. */
    showToast(
      copied
        ? "계좌번호가 복사되었습니다."
        : "복사하지 못했습니다. 길게 눌러 직접 복사해 주세요.",
    );
  };

  return (
    <Row>
      <Who>
        <Relation>{entry.relation}</Relation>
        <Name style={{ whiteSpace: "pre-line", lineHeight: 1.45 }}>
          {entry.name}
        </Name>
      </Who>
      <CopyButton
        type="button"
        onClick={handleCopy}
        aria-label={`${entry.relation} ${entry.name}의 계좌번호 ${entry.account.bank} ${entry.account.number} 복사`}
      >
        <AccountDetails>
          <Bank>{entry.account.bank}</Bank>
          <AccountNumber>{entry.account.number}</AccountNumber>
        </AccountDetails>
        <CopyHint aria-hidden="true">복사</CopyHint>
      </CopyButton>
    </Row>
  );
}

